SIM=/tmp/claude-1000/-home-moxa-sda2-home-moxa-WORK-ci-project/275fea54-ef70-47bf-987d-2b75de140b5c/scratchpad/bvtsim
rm -rf "$SIM"; mkdir -p "$SIM/bin" "$SIM/home" "$SIM/croot/app/switch_synergyautomation"
cat > "$SIM/bin/docker" <<'EOF'
#!/bin/bash
CROOT="$SIM_CROOT"
remap() { echo "${1/#\/app/$CROOT/app}"; }
case "$1" in
  start|stop) exit 0 ;;
  cp) src="${2#*:}"; dest="$3"; cp -r "$(remap "$src")" "$dest" 2>/dev/null || exit 1; exit 0 ;;
  exec)
    shift 2
    case "$1" in
      mkdir) shift; args=(); for a in "$@"; do [[ $a == /* ]] && args+=("$(remap "$a")") || args+=("$a"); done; mkdir "${args[@]}"; exit $? ;;
      rm) shift; args=(); for a in "$@"; do [[ $a == /* ]] && args+=("$(remap "$a")") || args+=("$a"); done; rm "${args[@]}"; exit $? ;;
      bash)
        CMD="$3"
        case "$CMD" in
          *"cd switch_synergyautomation && pwd"*) echo "/app/switch_synergyautomation"; exit 0 ;;
          *pytest*)
            XML=$(echo "$CMD" | grep -o -- '--junitxml=[^ ]*' | cut -d= -f2)
            ALL=$(echo "$CMD" | grep -o -- '--alluredir=[^ ]*' | cut -d= -f2)
            XML=$(remap "$XML"); ALL=$(remap "$ALL")
            mkdir -p "$(dirname "$XML")" "$ALL"
            RC=${FAKE_PYTEST_RC:-0}
            [ "$RC" = 0 ] && VERDICT='<testcase classname="t" name="case_a"/>' || VERDICT='<testcase classname="t" name="case_a"><failure message="boom"/></testcase>'
            printf '<testsuites><testsuite name="pytest" tests="1">%s</testsuite></testsuites>\n' "$VERDICT" > "$XML"
            echo "{}" > "$ALL/result.json"
            echo "testcase/t.py::case_a $([ "$RC" = 0 ] && echo PASSED || echo FAILED)"
            exit "$RC" ;;
          *) exit 0 ;;
        esac ;;
    esac ;;
esac
exit 0
EOF
chmod +x "$SIM/bin/docker"
mkdir -p "$SIM/home/download/synergy_switch_mds-g4000-l3_bvt/FWR_MDS-G4000-L3_v7.0_2026080701__daily_extracted"
touch "$SIM/home/download/synergy_switch_mds-g4000-l3_bvt/FWR_MDS-G4000-L3_v7.0_2026080701__daily_extracted/FWR_MDS-G4000-L3_v7.0.rom"
echo "SIM ready at $SIM"

